INSERT INTO `#__methodology_topics` (`slug`, `kind`, `status`, `title`, `tagline`, `short_description`, `description`, `author_slug`, `reviewer_slug`, `version`, `last_updated`, `tmpl`, `schema_type`, `external_url`, `sort_order`) VALUES ('fxrate', 'methodology', 'live', 'How FXRate Works: Welcome Packages, Advertised vs Effective', 'A welcome package headline adds the percentages and drops the deposits. FXRate puts the deposits back: what the casino prints, what you have to put in to collect it, the match rate on that money and the stake needed to clear it.', 'FXRate prices every multi-deposit welcome package from the operator terms listed on FreeExtraChips: advertised, deposit needed, effective match rate, turnover. Four numbers, no RTP, no simulation, nothing estimated; where a term is missing the line says not stated.', 'Methodology behind FXRate on FreeExtraChips bonus pages: how the advertised match of a welcome package is recomputed from its legs into the deposit needed, the effective match rate and the wagering turnover, the reading rules for missing caps, deposit limits, free spins and currencies, what FXRate is not, and how to verify it by hand.', 'david-romano', 'ethan-walker', 'v1.0', '2026-10-15', 'fxrate', NULL, NULL, 37) ON DUPLICATE KEY UPDATE `kind` = VALUES(`kind`), `status` = VALUES(`status`), `title` = VALUES(`title`), `tagline` = VALUES(`tagline`), `short_description` = VALUES(`short_description`), `description` = VALUES(`description`), `author_slug` = VALUES(`author_slug`), `reviewer_slug` = VALUES(`reviewer_slug`), `tmpl` = VALUES(`tmpl`), `version` = VALUES(`version`), `last_updated` = VALUES(`last_updated`), `sort_order` = VALUES(`sort_order`);
